<?php
allow($page==='approvals'?['chairperson']:['treasurer']);$ps=projectList();$budget=array_sum(array_column($ps,'budget_cents'));$released=array_sum(array_column($ps,'released_cents'));$totalSpent=array_sum(array_column($ps,'spent'));
if($page==='balance'): ?>
<section class="panel"><h2>Total Fund</h2><div class="balance-banner"><small>Total Fund Balance (approved budgets less expenses)</small><?= money($budget-$totalSpent) ?></div><p class="note">Released but unspent: <?= money($released-$totalSpent) ?>. Unreleased approved budgets: <?= money($budget-$released) ?>. Unallocated source funds appear under Allocation.</p></section><section class="panel"><h2>Per Project</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Project Name</th><th>Approved Budget</th><th>Released</th><th>Spent</th><th>Fund Balance</th></tr></thead><tbody><?php foreach($ps as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= money($p['budget_cents']) ?></td><td><?= money($p['released_cents']) ?></td><td><?= money($p['spent']) ?></td><td><?= money($p['budget_cents']-$p['spent']) ?></td></tr><?php endforeach;if(!$ps)emptyRow(5); ?></tbody></table></div></section>
<?php elseif($page==='allocation'): ?>
<div class="grid three metrics"><?php metric('Total Planned Budget',money(array_sum(array_column($ps,'planned_cents'))),'₱');metric('Total Approved / Adjusted Budget',money($budget),'₱');metric('Total Released',money($released),'₱'); ?></div>
<section class="panel"><h2>Budget Allocation</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Project</th><th>Category</th><th>Planned Budget</th><th>Approved Budget</th><th>Released</th><th>Review Status</th></tr></thead><tbody><?php foreach($ps as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= e($p['category']) ?></td><td><?= money($p['planned_cents']) ?></td><td><?= money($p['budget_cents']) ?></td><td><?= money($p['released_cents']) ?></td><td><?= badge($p['review_status']) ?></td></tr><?php endforeach;if(!$ps)emptyRow(6); ?></tbody></table></div></section>
<div class="grid two"><section class="panel"><h2>Allocation / Realignment / Disbursement Request</h2><p class="note">Allocations reserve recorded source funds. Realignments transfer unreleased budget between projects using the same source. Disbursements release approved budget for expenses. The Chairperson approves every request.</p><form method="post" enctype="multipart/form-data"><?php actionFields('fund_request');selectField('Request Type','type',['Allocation'=>'Set / Increase Budget','Realignment'=>'Realign Fund','Disbursement'=>'Release Fund']);projectSelect('project_id','',true);$opts=[];foreach($ps as $p)$opts[$p['id']]=$p['title'].' — available '.money($p['budget_cents']-$p['released_cents']);selectField('Source Project (realignment only)','from_project_id',[''=>'Not applicable']+$opts,'',false);field('Amount (PHP)','amount','','number',true,'min="0.01" step="0.01"');textarea('Reason','reason');field('Supporting Document (optional; image or PDF, max 5 MB)','document','','file',false,'accept="image/jpeg,image/png,image/webp,application/pdf"'); ?><button>Submit for Approval</button></form></section>
<section class="panel"><h2>Fund Sources / Balance Summary</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Source</th><th>Received</th><th>Unallocated</th></tr></thead><tbody><?php $sources=rows('SELECT f.*,COALESCE((SELECT SUM(amount_cents) FROM fund_entries WHERE source_id=f.id),0) received,COALESCE((SELECT SUM(budget_cents) FROM projects WHERE source_id=f.id),0) allocated FROM fund_sources f ORDER BY name');foreach($sources as $f): ?><tr><td><?= e($f['name']) ?></td><td><?= money($f['received']) ?></td><td><?= money($f['received']-$f['allocated']) ?></td></tr><?php endforeach;if(!$sources)emptyRow(3,'Ask your Admin to configure fund sources.'); ?></tbody></table></div><details><summary>Record funds received from authorized records</summary><p class="note">This records an actual funding receipt. It does not connect to a bank account. Amounts become available for project allocation.</p><form method="post" data-confirm="Record this funding receipt? Ensure the amount and reference match your authorized records."><?php actionFields('fund_entry');selectField('Fund Source','source_id',options('fund_sources'));field('Amount (PHP)','amount','','number',true,'min="0.01" step="0.01"');field('Date Received','entry_date',date('Y-m-d'),'date');field('Authorization / Reference','reference','','text',true,'maxlength="150"'); ?><button>Record Funding</button></form></details></section></div>
<section class="panel"><h2>Request History</h2><?php requestTable(false); ?></section>
<?php elseif($page==='approvals'): ?>
<section class="panel"><h2>Fund Requests</h2><p class="note">Approval posts the financial change once. A request cannot be approved twice, and amounts cannot exceed the available recorded balance.</p><?php requestTable(true); ?></section>
<?php elseif($page==='expenses'): $edit=isset($_GET['edit'])?one('SELECT * FROM expenses WHERE id=?',[(int)$_GET['edit']]):null; ?>
<section class="panel"><h2><?= $edit?'Edit Expense':'Add Expense' ?></h2><p class="note">Record actual expenses against released funds. Upload a receipt image and enter its date, supplier/payee, reference and amount. Maximum image size: 5 MB.</p><form method="post" enctype="multipart/form-data"><?php actionFields('expense'); ?><input type="hidden" name="id" value="<?= e($edit['id']??0) ?>"><div class="grid two"><div><h3>Expense Information</h3><?php projectSelect('project_id',$edit['project_id']??'',true);field('Amount (PHP)','amount',$edit?number_format($edit['amount_cents']/100,2,'.',''):'','number',true,'min="0.01" step="0.01"');field('Expense Date','expense_date',$edit['expense_date']??date('Y-m-d'),'date');textarea('Expense Description','description',$edit['description']??''); ?></div><div><h3>Receipt Details</h3><?php field('Supplier / Payee','payee',$edit['payee']??'','text',true,'maxlength="190"');field('Receipt Date','receipt_date',$edit['receipt_date']??date('Y-m-d'),'date');field('Receipt Number / Reference','receipt_reference',$edit['receipt_reference']??'','text',true,'maxlength="120"');field($edit?'Replace Receipt Image (optional)':'Receipt Image','receipt','','file',!$edit,'accept="image/jpeg,image/png,image/webp"');if($edit): ?><a target="_blank" rel="noopener" href="<?= e(url('file',['kind'=>'receipt','id'=>$edit['id']])) ?>">View current receipt</a><?php endif ?></div></div><div class="actions"><a class="button secondary" href="<?= e(url('transactions')) ?>">Cancel</a><button><?= $edit?'Save Changes':'Record Expense' ?></button></div></form></section>
<?php else:
$q=is_string($_GET['q']??null)?trim($_GET['q']):'';$from=is_string($_GET['from']??null)?$_GET['from']:'';$to=is_string($_GET['to']??null)?$_GET['to']:'';
$where=['(p.title LIKE ? OR x.payee LIKE ? OR x.receipt_reference LIKE ?)'];$args=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];if($from!==''){$where[]='x.expense_date>=?';$args[]=$from;}if($to!==''){$where[]='x.expense_date<=?';$args[]=$to;}
$expenses=rows('SELECT x.*,p.title FROM expenses x JOIN projects p ON p.id=x.project_id WHERE '.implode(' AND ',$where).' ORDER BY x.expense_date DESC,x.id DESC',$args); ?>
<section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="transactions"><?php field('Search project, supplier or receipt','q',$q,'search',false);field('From','from',$from,'date',false);field('To','to',$to,'date',false); ?><button>Apply</button><a class="button secondary" href="<?= e(url('transactions')) ?>">Reset</a></form><div class="section-heading"><h2>Expenses / Receipts</h2><a class="button small" href="<?= e(url('expenses')) ?>">+ Add Expense</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date</th><th>Project</th><th>Supplier</th><th>Amount</th><th>Receipt Reference</th><th>Action</th></tr></thead><tbody><?php foreach($expenses as $x): ?><tr><td><?= e($x['expense_date']) ?></td><td><?= e($x['title']) ?></td><td><?= e($x['payee']) ?></td><td><?= money($x['amount_cents']) ?></td><td><?= e($x['receipt_reference']) ?></td><td><div class="inline"><a href="<?= e(url('file',['kind'=>'receipt','id'=>$x['id']])) ?>" target="_blank" rel="noopener">View Receipt</a><a href="<?= e(url('expenses',['edit'=>$x['id']])) ?>">Edit</a></div></td></tr><?php endforeach;if(!$expenses)emptyRow(6); ?></tbody></table></div></section><section class="panel"><h2>Fund Transaction History</h2><?php requestTable(false); ?></section><section class="panel"><h2>Funds Received</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date</th><th>Fund Source</th><th>Reference</th><th>Amount</th></tr></thead><tbody><?php $entries=rows('SELECT e.*,f.name FROM fund_entries e JOIN fund_sources f ON f.id=e.source_id ORDER BY e.entry_date DESC,e.id DESC');foreach($entries as $r): ?><tr><td><?= e($r['entry_date']) ?></td><td><?= e($r['name']) ?></td><td><?= e($r['reference']) ?></td><td><?= money($r['amount_cents']) ?></td></tr><?php endforeach;if(!$entries)emptyRow(4); ?></tbody></table></div></section>
<?php endif;
function requestTable(bool $approve): void {
    $requests=rows('SELECT r.*,p.title,u.name requester,s.title from_title FROM fund_requests r JOIN projects p ON p.id=r.project_id JOIN users u ON u.id=r.requested_by LEFT JOIN projects s ON s.id=r.from_project_id ORDER BY r.id DESC');
?>
<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date</th><th>Project / Request</th><th>Amount</th><th>Status</th><th>Details / Action</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><?= e($r['created_at']) ?></td><td><?= e($r['title']) ?><br><small><?= e($r['type']) ?> · <?= e($r['requester']) ?></small></td><td><?= money($r['amount_cents']) ?></td><td><?= badge($r['status']) ?></td><td><details><summary>View Details<?= $approve && $r['status']==='Pending'?' / Decide':'' ?></summary><p><?= e($r['reason']) ?></p><?php if($r['from_title']): ?><p>Source project: <?= e($r['from_title']) ?></p><?php endif;if($r['document_path']): ?><a href="<?= e(url('file',['kind'=>'document','id'=>$r['id']])) ?>" target="_blank" rel="noopener">Supporting Document</a><?php endif;if($r['decision_notes']): ?><p>Decision: <?= e($r['decision_notes']) ?></p><?php endif;if($approve && $r['status']==='Pending'): ?><form method="post" data-confirm="Submit this financial decision? Approved changes will be posted to the budget ledger."><?php actionFields('decide_request'); ?><input type="hidden" name="id" value="<?= e($r['id']) ?>"><?php textarea('Decision Notes','decision_notes','',false,3000);selectField('Decision','decision',['Approved'=>'Approve','Rejected'=>'Reject']); ?><button>Save Decision</button></form><?php endif ?></details></td></tr><?php endforeach;if(!$requests)emptyRow(5); ?></tbody></table></div>
<?php }
